package de.lazytv.pro.catalog;
import de.lazytv.pro.activation.ActivationGuard;import android.app.*;import android.os.*;import android.widget.*;import java.util.*;import java.util.concurrent.*;import de.lazytv.pro.R;import de.lazytv.pro.playlist.*;import de.lazytv.pro.player.PlayerLauncher;
public class SeriesDetailActivity extends Activity {public static final String PLAYLIST="playlist_id",SERIES_ID="series_id",SERIES_NAME="series_name",SERIES_LOGO="series_logo",SERIES_CAT="series_cat";private final ExecutorService pool=Executors.newSingleThreadExecutor();private CatalogEngine engine=new CatalogEngine();private Playlist p;private Series series;private SeriesDetails details;private ArrayAdapter<String> adapter;private ListView list;private TextView status,title;private int selectedSeason=-1;private Season selectedSeasonItem=null;protected void onCreate(Bundle b){super.onCreate(b);if(!ActivationGuard.enforce(this))return;setContentView(R.layout.activity_series_detail);p=new PlaylistStorage(this).get(getIntent().getStringExtra(PLAYLIST));series=new Series(getIntent().getStringExtra(SERIES_ID),getIntent().getStringExtra(SERIES_NAME),getIntent().getStringExtra(SERIES_CAT),getIntent().getStringExtra(SERIES_LOGO),"","");if(p==null||series.id==null){finish();return;}title=findViewById(R.id.series_title);status=findViewById(R.id.series_status);list=findViewById(R.id.series_list);adapter=new ArrayAdapter<>(this,android.R.layout.simple_list_item_1,new ArrayList<>());list.setAdapter(adapter);title.setText(series.name);list.setOnItemClickListener((a,v,pos,id)->click(pos));load();}private void load(){status.setText("Duke ngarkuar sezonet…");pool.execute(()->{try{SeriesDetails d=engine.loadSeries(p,series);runOnUiThread(()->{if(isFinishing())return;details=d;showSeasons();});}catch(Exception e){runOnUiThread(()->status.setText(msg(e,"Seriali nuk mund të ngarkohet")));}});}private void showSeasons(){selectedSeason=-1;selectedSeasonItem=null;adapter.clear();for(Season s:details.seasons)adapter.add(s.title);status.setText(details.seasons.size()+" sezone");}private void showEpisodes(Season season){selectedSeasonItem=season;selectedSeason=season.number;adapter.clear();List<Episode> es=details.episodes.get(season.number);if(es!=null)for(Episode e:es)adapter.add((e.episodeNumber>0?e.episodeNumber+". ":"")+e.name);status.setText((es==null?0:es.size())+" episode");}private void click(int pos){if(selectedSeason<0){Season s=details.seasons.get(pos);showEpisodes(s);return;}List<Episode> es=details.episodes.get(selectedSeason);if(es==null||pos>=es.size())return;Episode ep=es.get(pos);status.setText("Duke përgatitur stream-in…");pool.execute(()->{try{ResolvedStream rs=engine.resolveStream(p,ep);runOnUiThread(()->{status.setText("Stream gati");PlayerLauncher.open(this,p.getId(),ep,rs,series.name);});}catch(Exception e){runOnUiThread(()->status.setText("Stream-i nuk mund të zgjidhet"));}});}@Override public void onBackPressed(){if(selectedSeason>=0)showSeasons();else super.onBackPressed();}private String msg(Exception e,String d){return e.getMessage()==null?d:e.getMessage();}protected void onDestroy(){pool.shutdownNow();engine.close();super.onDestroy();}}